import {useWritingRequest} from './writing-request.js';
import React,{useState} from 'react';
import {useResource} from './state.js';
import {ResourceState} from './ui.jsx';
export function WritingHistory({call,novelId,collection,id,revision,nodeRevision,run,busy,dirty=false,restored,labels={},nodes=[],chapters=[]}){
 const write=useWritingRequest(call);
 const [opened,setOpened]=useState(false),[poll,setPoll]=useState(0),[error,setError]=useState('');
 const resource=useResource(()=>opened?call('writing.history',{novelId,collection,id}):Promise.resolve(null),[call,novelId,collection,id,opened,poll]);
 return <details onToggle={e=>setOpened(e.currentTarget.open)}><summary>历史恢复</summary>{error&&<p className="notice error" role="alert">{error}</p>}{opened&&<ResourceState resource={resource}>{resource.value?.versions.length===0&&<p className="muted">尚无旧版本。</p>}{resource.value?.versions.map(v=><div className="structure-entry" key={v.revision}><p>版本 {v.revision} · {v.actor?.kind==='agent'?'AI':'作者'} · {v.reason}</p><details><summary>查看保存内容</summary>{v.value.storyTime&&<p>故事时间：{v.value.storyTime} · 排序 {v.value.order}</p>}{v.value.value&&<><h4>{v.value.value.name||'关系状态'}</h4><p>{v.value.value.content}</p><p>{v.value.value.active?'存在':'结束／暂时不存在'}</p></>}{v.value.deleted&&<p>已移出当前记录</p>}{v.value.chapterRefs?.map((r,i)=><p key={i}>{chapters.find(c=>c.id===r.chapterId)?.title||'章节呈现'} · 版本 {r.revision}<br/>{r.evidence}</p>)}{v.value.title&&<h4>{v.value.title}</h4>}{v.value.status&&<p>{{planned:'计划',planted:'已埋设',developing:'推进中',recovered:'已回收',abandoned:'已放弃'}[v.value.status]}</p>}{v.value.content&&<p>{v.value.content}</p>}{v.value.abandonReason&&<p>放弃原因：{v.value.abandonReason}</p>}{v.value.aliases?.length>0&&<p>别名：{v.value.aliases.join('、')}</p>}{v.value.values&&<dl className="structured-values">{Object.entries(v.value.values).map(([key,value])=><React.Fragment key={key}><dt>{labels[key]||'归档字段'}</dt><dd>{Array.isArray(value)?value.map(id=>nodes.find(n=>n.id===id)?.name||id).join('、'):String(value??'')}</dd></React.Fragment>)}</dl>}{v.value.evidence?.map((e,i)=><div key={i}><small>{{plant:'埋设',progress:'推进',recover:'回收'}[e.kind]} · {chapters.find(c=>c.id===e.chapterId)?.title||'正文依据'} · 版本 {e.revision}</small><blockquote>{e.evidence}</blockquote></div>)}</details><button disabled={busy||dirty} title={dirty?'先保存或放弃本地草稿':undefined} onClick={()=>run(async()=>{setError('');try{await write('writing.restore',{novelId,collection,id,expectedRevision:revision,expectedNodeRevision:nodeRevision,targetRevision:v.revision,reason:'作者恢复结构资料历史'});setPoll(n=>n+1);restored();}catch(e){setError(e.message);throw e;}})}>恢复这版</button></div>)}</ResourceState>}</details>;
}
